    big: {f: 4, per: 'state', src: '闪序列大字 n=30'},
    build: {f: 82, per: 'event', src: '渐进文字（整段事件）'},
    count: {f: 4, per: 'state', src: '倒数 n=3'},
    code: {f: 41, per: 'card', src: '符号／代码 5W1H'},
